from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class CheckKind(Enum):
    """The kinds of checks performed for each package change."""

    CI_UPLOAD = "ci_upload"
    RELEASE_PIPELINE = "release_pipeline"
    REPO_PUBLIC = "repo_public"
    PR_LINK = "pr_link"


class CheckStatus(Enum):
    """The possible outcomes of a single check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    NEEDS_AGENT = "needs_agent"


@dataclass
class CheckResult:
    """The result of a single check."""

    status: CheckStatus
    details: str


@dataclass
class PackageChange:
    """A single package version change detected in a diff."""

    name: str
    old_version: str | None
    new_version: str
    checks: dict[CheckKind, CheckResult] = field(default_factory=dict)
    repo_url: str | None = None

    @property
    def needs_agent(self) -> bool:
        """Return True if any check needs agent follow-up."""
        return any(
            result.status is CheckStatus.NEEDS_AGENT
            for result in self.checks.values()
        )


@dataclass
class CheckRunResult:
    """The result of running all checks for a PR."""

    pr_number: int
    packages: list[PackageChange] = field(default_factory=list)

    @property
    def needs_agent(self) -> bool:
        """Return True if any contained package needs agent follow-up."""
        return any(package.needs_agent for package in self.packages)

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-serializable representation of the run."""
        # Imported lazily to avoid a circular import with the render module.
        from .render import render_comment

        result: dict[str, Any] = {
            "pr_number": self.pr_number,
            "rendered_comment": render_comment(self),
            "needs_agent": self.needs_agent,
            "checks": [kind.value for kind in CheckKind],
            "packages": [self._package_to_dict(package) for package in self.packages],
        }
        # Expose a per-kind summary under each lowercase check-kind name.
        for kind in CheckKind:
            result[kind.value] = {
                package.name: package.checks[kind].status.value
                for package in self.packages
                if kind in package.checks
            }
        return result

    @staticmethod
    def _package_to_dict(package: PackageChange) -> dict[str, Any]:
        """Return a JSON-serializable representation of a package change."""
        return {
            "name": package.name,
            "old_version": package.old_version,
            "new_version": package.new_version,
            "repo_url": package.repo_url,
            "needs_agent": package.needs_agent,
            "checks": {
                kind.value: {
                    "status": result.status.value,
                    "details": result.details,
                }
                for kind, result in package.checks.items()
            },
        }
