from __future__ import annotations

import re
from fnmatch import fnmatch

from .models import PackageChange

# Matches a pinned requirement line, e.g. ``Foo_Bar[extra]==1.2.3``.
_REQUIREMENT_RE = re.compile(
    r"^([A-Za-z0-9][A-Za-z0-9._-]*)\s*(?:\[[^\]]*\])?\s*==\s*([^\s;#]+)"
)


def _canonical_name(name: str) -> str:
    """Normalize a package name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name.strip()).lower()


def _is_tracked(path: str) -> bool:
    """Return True if the file path is a tracked requirements file."""
    basename = path.replace("\\", "/").rsplit("/", 1)[-1]
    return fnmatch(basename, "requirements*.txt")


def _parse_requirement(content: str) -> tuple[str, str] | None:
    """Parse a single requirement line into (canonical_name, version)."""
    content = content.strip()
    if not content or content.startswith("#"):
        return None
    # Strip any inline comment before parsing.
    content = content.split("#", 1)[0].strip()
    if not content:
        return None
    match = _REQUIREMENT_RE.match(content)
    if match is None:
        return None
    return _canonical_name(match.group(1)), match.group(2).strip()


def parse_diff(diff_text: str) -> list[PackageChange]:
    """Parse a unified diff and return the package version changes."""
    changes: list[PackageChange] = []
    tracked = False
    removed: dict[str, str] = {}
    added: dict[str, str] = {}
    order: list[str] = []

    def flush() -> None:
        for name in order:
            new_version = added.get(name)
            if new_version is None:
                continue
            old_version = removed.get(name)
            if old_version == new_version:
                # No version change; ignore.
                continue
            changes.append(
                PackageChange(
                    name=name,
                    old_version=old_version,
                    new_version=new_version,
                )
            )

    for line in diff_text.splitlines():
        if line.startswith("+++ "):
            # A new file section begins; flush the previous one.
            flush()
            removed = {}
            added = {}
            order = []
            path = line[4:].strip().split("\t", 1)[0].split()[0] if line[4:].strip() else ""
            tracked = _is_tracked(path)
            continue
        if line.startswith("--- ") or line.startswith("diff --git") or line.startswith("@@"):
            continue
        if not tracked:
            continue
        if line.startswith("+"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                name, version = parsed
                if name not in added and name not in removed:
                    order.append(name)
                elif name not in added and name not in order:
                    order.append(name)
                added[name] = version
        elif line.startswith("-"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                name, version = parsed
                if name not in order:
                    order.append(name)
                removed[name] = version

    flush()
    return changes
