from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any
from urllib.parse import urlparse

import requests

_TIMEOUT = 30

# Hostnames that are recognized code-hosting services.
_CODE_HOSTS = {
    "github.com",
    "gitlab.com",
    "www.github.com",
    "www.gitlab.com",
}

# Publisher kinds that are recognized as trusted PEP 740 publishers.
_RECOGNIZED_PUBLISHERS = {"GitHub"}


@dataclass
class PypiPackageInfo:
    """Information fetched from PyPI for a specific package version."""

    project_urls: dict[str, Any] = field(default_factory=dict)
    repo_url: str | None = None
    file_provenance_urls: list[str] = field(default_factory=list)
    found: bool = False


@dataclass
class ProvenanceResult:
    """The result of a provenance/attestation check."""

    has_attestation: bool
    publisher_kind: str | None
    recognized_publisher: bool
    detail: str


def _strip_control(value: str) -> str:
    """Strip backtick and newline characters from a string."""
    return value.replace("`", "").replace("\r", "").replace("\n", "")


def _get_json(url: str) -> tuple[int | None, Any]:
    """Fetch a URL and return (status, json).

    ``status`` is the HTTP status code, or ``None`` for a network error, a
    5xx/other non-200 response, or a body that is not valid JSON. When
    ``status`` is 404 the JSON body is ``None``.
    """
    try:
        response = requests.get(url, timeout=_TIMEOUT)
    except requests.RequestException:
        return None, None
    if response.status_code == 404:
        return 404, None
    if response.status_code != 200:
        # 5xx or any other unexpected status is treated as an error.
        return None, None
    try:
        return 200, response.json()
    except ValueError:
        return None, None


def _extract_project_urls(data: Any) -> dict[str, Any]:
    """Return the project_urls mapping from a PyPI JSON response."""
    info = data.get("info") if isinstance(data, dict) else None
    if not isinstance(info, dict):
        return {}
    project_urls = info.get("project_urls")
    if not isinstance(project_urls, dict):
        return {}
    return dict(project_urls)


def _is_code_host_url(value: Any) -> bool:
    """Return True if the value is a URL hosted on a known code host."""
    if not isinstance(value, str):
        return False
    try:
        parsed = urlparse(value)
    except ValueError:
        return False
    host = (parsed.hostname or "").lower()
    return host in _CODE_HOSTS


def _select_repo_url(project_urls: dict[str, Any]) -> str | None:
    """Select a repository URL from the project URLs mapping."""
    # Prefer explicit source/repository keys.
    for key in ("Source", "Repository"):
        value = project_urls.get(key)
        if _is_code_host_url(value):
            return _strip_control(value)
    # Otherwise scan every value for a known code-host URL.
    for value in project_urls.values():
        if _is_code_host_url(value):
            return _strip_control(value)
    return None


def _build_provenance_urls(name: str, version: str, data: Any) -> list[str]:
    """Build provenance URLs from the first file in the PyPI response."""
    files = data.get("urls") if isinstance(data, dict) else None
    if not isinstance(files, list) or not files:
        return []
    first = files[0]
    filename = first.get("filename") if isinstance(first, dict) else None
    if not filename:
        return []
    return [
        f"https://pypi.org/integrity/{name}/{version}/{filename}/provenance"
    ]


def fetch_package_info(name: str, version: str) -> PypiPackageInfo:
    """Fetch package metadata from PyPI for a specific version."""
    versioned_url = f"https://pypi.org/pypi/{name}/{version}/json"
    status, data = _get_json(versioned_url)

    if status == 200 and data is not None:
        project_urls = _extract_project_urls(data)
        return PypiPackageInfo(
            project_urls=project_urls,
            repo_url=_select_repo_url(project_urls),
            file_provenance_urls=_build_provenance_urls(name, version, data),
            found=True,
        )

    if status == 404:
        # Fall back to the latest-version endpoint for metadata only.
        latest_url = f"https://pypi.org/pypi/{name}/json"
        latest_status, latest_data = _get_json(latest_url)
        if latest_status == 200 and latest_data is not None:
            project_urls = _extract_project_urls(latest_data)
            return PypiPackageInfo(
                project_urls=project_urls,
                repo_url=_select_repo_url(project_urls),
                file_provenance_urls=[],
                found=False,
            )
        return PypiPackageInfo(
            project_urls={}, repo_url=None, file_provenance_urls=[], found=False
        )

    # Network error, 5xx, or invalid JSON.
    return PypiPackageInfo(
        project_urls={}, repo_url=None, file_provenance_urls=[], found=False
    )


