from __future__ import annotations

from .models import CheckKind, CheckRunResult, CheckStatus, PackageChange

MARKER = "<!-- requirements-check -->"

# The order in which check kinds are displayed.
_ALL_KINDS = [
    CheckKind.CI_UPLOAD,
    CheckKind.RELEASE_PIPELINE,
    CheckKind.REPO_PUBLIC,
    CheckKind.PR_LINK,
]

_STATUS_ICON = {
    CheckStatus.PASS: "✅",
    CheckStatus.WARN: "⚠️",
    CheckStatus.FAIL: "❌",
    CheckStatus.NEEDS_AGENT: "🔍",
}

_SKIPPED_CELL = "—"


def _cell_placeholder(package_name: str, kind: CheckKind) -> str:
    return "{{CHECK_CELL:" + package_name + ":" + kind.value + "}}"


def _detail_placeholder(package_name: str, kind: CheckKind) -> str:
    return "{{CHECK_DETAIL:" + package_name + ":" + kind.value + "}}"


def _all_pass(result: CheckRunResult) -> bool:
    """Return True when every check on every package passed."""
    saw_check = False
    for package in result.packages:
        for check in package.checks.values():
            saw_check = True
            if check.status is not CheckStatus.PASS:
                return False
    return saw_check


def _render_table(result: CheckRunResult) -> list[str]:
    lines: list[str] = []
    header = "| Package | " + " | ".join(k.value for k in _ALL_KINDS) + " |"
    separator = "| --- " * (len(_ALL_KINDS) + 1) + "|"
    lines.append(header)
    lines.append(separator)
    for package in result.packages:
        cells: list[str] = []
        for kind in _ALL_KINDS:
            check = package.checks.get(kind)
            if check is None:
                cells.append(_SKIPPED_CELL)
            elif check.status is CheckStatus.NEEDS_AGENT:
                cells.append(_cell_placeholder(package.name, kind))
            else:
                cells.append(_STATUS_ICON[check.status])
        lines.append("| " + package.name + " | " + " | ".join(cells) + " |")
    return lines


def _render_package_details(package: PackageChange) -> list[str]:
    lines: list[str] = []
    old = package.old_version if package.old_version is not None else "(new)"
    lines.append(f"### `{package.name}` {old} → {package.new_version}")
    for kind in _ALL_KINDS:
        check = package.checks.get(kind)
        if check is None:
            lines.append(f"- **{kind.value}**: — skipped.")
        elif check.status is CheckStatus.NEEDS_AGENT:
            lines.append(
                f"- **{kind.value}**: {_detail_placeholder(package.name, kind)}"
            )
        else:
            icon = _STATUS_ICON[check.status]
            lines.append(f"- **{kind.value}**: {icon} {check.details}")
    return lines


def render_comment(result: CheckRunResult) -> str:
    """Render a Markdown comment for a check run."""
    lines: list[str] = [MARKER, "", "## Requirements supply-chain check", ""]

    if not result.packages:
        lines.append("No tracked requirement changes detected.")
        return "\n".join(lines)

    if _all_pass(result):
        lines.append("All requirements checks passed. ✅")
        lines.append("")

    details_tag = "<details open>" if result.needs_agent else "<details>"
    lines.append(details_tag)
    lines.append("<summary>Per-package results</summary>")
    lines.append("")
    lines.extend(_render_table(result))
    lines.append("")
    for package in result.packages:
        lines.extend(_render_package_details(package))
        lines.append("")
    lines.append("</details>")

    return "\n".join(lines)
