from __future__ import annotations

from .diff import parse_diff
from .models import CheckKind, CheckResult, CheckRunResult, CheckStatus
from .pypi import PypiPackageInfo, check_provenance, fetch_package_info


def _checks_for_missing_package() -> dict[CheckKind, CheckResult]:
    """Build the checks for a package version not present on PyPI."""
    detail = "Package version was not found on PyPI."
    return {
        CheckKind.CI_UPLOAD: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.RELEASE_PIPELINE: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.REPO_PUBLIC: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.PR_LINK: CheckResult(CheckStatus.FAIL, detail),
    }


def _run_package_checks(info: PypiPackageInfo) -> dict[CheckKind, CheckResult]:
    """Run all checks for a single package given its PyPI info."""
    if not info.found:
        return _checks_for_missing_package()

    provenance = check_provenance(info)
    checks: dict[CheckKind, CheckResult] = {}

    if provenance.recognized_publisher:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.PASS,
            "Uploaded to PyPI with a recognized publisher "
            f"('{provenance.publisher_kind}').",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.PASS,
            "Release pipeline verified via PEP 740 attestation "
            f"({provenance.publisher_kind}).",
        )
    elif provenance.has_attestation:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            "Attestation present but the publisher "
            f"('{provenance.publisher_kind}') is not recognised.",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "Attestation publisher unrecognised "
            f"('{provenance.publisher_kind}'); manual review required.",
        )
    else:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            provenance.detail or "No provenance attestation present.",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "No release-pipeline attestation found; manual review required.",
        )

    if info.repo_url:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Verify that {info.repo_url} is a public source repository.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Verify the release PR/commit link in {info.repo_url}.",
        )
    else:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.FAIL,
            "Package does not advertise a source repository URL.",
